mapper.select:
SELECT
(SELECT COUNT(*) FROM employee e WHERE 1 = 1
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND e.created_at >= #{from}
    AND e.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS employee_count,
(SELECT COUNT(*) FROM employee_archive ea JOIN employee e ON e.id = ea.employee_id
 WHERE ea.completeness >= 100
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND e.created_at >= #{from}
    AND e.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS complete_archive_count,
(SELECT COUNT(*) FROM employee_archive ea JOIN employee e ON e.id = ea.employee_id
 WHERE 1 = 1
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND e.created_at >= #{from}
    AND e.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS archive_count,
(SELECT COUNT(*) FROM hr_request r JOIN employee e ON e.id = r.employee_id
 WHERE 1 = 1
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND r.created_at >= #{from}
    AND r.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS workflow_count,
(SELECT COUNT(*) FROM hr_request r JOIN employee e ON e.id = r.employee_id
 WHERE r.status LIKE 'PENDING%'
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND r.created_at >= #{from}
    AND r.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS pending_workflow_count,
(SELECT COUNT(*) FROM archive_access_application a WHERE a.status = 'IN_USE'
    AND 1 = 1
        AND a.department_id = #{departmentId}

            AND EXISTS (SELECT 1 FROM sys_user u WHERE u.id = a.applicant_id AND u.employee_id = #{employeeId})

        AND 1 = 0
    AND a.created_at >= #{from}
    AND a.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS active_access_count,
(SELECT COUNT(*) FROM archive_access_application a WHERE a.status = 'ABNORMAL'
    AND 1 = 1
        AND a.department_id = #{departmentId}

            AND EXISTS (SELECT 1 FROM sys_user u WHERE u.id = a.applicant_id AND u.employee_id = #{employeeId})

        AND 1 = 0
    AND a.created_at >= #{from}
    AND a.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS abnormal_access_count,
(SELECT COUNT(*) FROM ocr_binding b JOIN archive_version v ON v.id = b.archive_version_id
  JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id
 WHERE b.status = 'SUCCEEDED'
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND b.created_at >= #{from}
    AND b.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS ocr_succeeded_count,
(SELECT COUNT(*) FROM ocr_binding b JOIN archive_version v ON v.id = b.archive_version_id
  JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id
 WHERE b.status = 'FAILED'
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND b.created_at >= #{from}
    AND b.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS ocr_failed_count,
(SELECT COUNT(*) FROM ocr_binding b JOIN archive_version v ON v.id = b.archive_version_id
  JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id
 WHERE b.review_required = TRUE
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND b.created_at >= #{from}
    AND b.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS ocr_review_count,
(SELECT COALESCE(SUM(b.processing_duration_ms), 0) FROM ocr_binding b JOIN archive_version v ON v.id = b.archive_version_id
  JOIN archive_document d ON d.id = v.document_id JOIN employee e ON e.id = d.employee_id
 WHERE 1 = 1
    AND 1 = 1
        AND e.department_id = #{departmentId}
        AND e.id = #{employeeId}
        AND 1 = 0
    AND b.created_at >= #{from}
    AND b.created_at < DATE_ADD(#{to}, INTERVAL 1 DAY)) AS ocr_duration_total_ms
